-- ════════════════════════════════════════════════════════════════════════════

-- The "Gift & Travel" TV campaign belonged to the template's previous client and
-- is not part of this site. Remove its tables (the site no longer reads them).
DROP TABLE IF EXISTS gift_travel_episodes CASCADE;
DROP TABLE IF EXISTS sponsors CASCADE;

-- ════════════════════════════════════════════════════════════════════════════
-- 012_tour_translations_currency.sql
-- ════════════════════════════════════════════════════════════════════════════

-- Phase 2: languages and currency.
-- 1) Tour text per language in one jsonb column instead of *_en columns:
--    { "en": { "title": "...", "shortDescription": "...", "description": "...",
--              "includes": [...], "excludes": [...], "itinerary": [...] } }
--    The columns title / description / short_description / includes / excludes /
--    itinerary hold the DEFAULT language (Italian).
-- 2) Each tour is priced in its own currency (EUR or USD).
-- 3) Bookings remember the currency they were made in; locale becomes it | en.

ALTER TABLE tours ADD COLUMN IF NOT EXISTS translations jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE tours ADD COLUMN IF NOT EXISTS currency text NOT NULL DEFAULT 'EUR'
  CHECK (currency IN ('EUR', 'USD'));

-- Keep any existing English text.
UPDATE tours
SET translations = jsonb_strip_nulls(jsonb_build_object('en', jsonb_build_object(
  'title', NULLIF(title_en, ''),
  'shortDescription', NULLIF(short_description_en, ''),
  'description', NULLIF(description_en, ''),
  'includes', CASE WHEN COALESCE(array_length(includes_en, 1), 0) > 0 THEN to_jsonb(includes_en) END,
  'excludes', CASE WHEN COALESCE(array_length(excludes_en, 1), 0) > 0 THEN to_jsonb(excludes_en) END,
  'itinerary', itinerary_en
)))
WHERE translations = '{}'::jsonb
  AND (title_en IS NOT NULL OR short_description_en IS NOT NULL OR description_en IS NOT NULL OR itinerary_en IS NOT NULL);

ALTER TABLE tours
  DROP COLUMN IF EXISTS title_en,
  DROP COLUMN IF EXISTS short_description_en,
  DROP COLUMN IF EXISTS description_en,
  DROP COLUMN IF EXISTS includes_en,
  DROP COLUMN IF EXISTS excludes_en,
  DROP COLUMN IF EXISTS itinerary_en,
  DROP COLUMN IF EXISTS inclusions_en,
  DROP COLUMN IF EXISTS exclusions_en,
  DROP COLUMN IF EXISTS price_usd;

ALTER TABLE bookings ADD COLUMN IF NOT EXISTS currency text NOT NULL DEFAULT 'EUR'
  CHECK (currency IN ('EUR', 'USD'));

-- Booking language: Italian (default) or English.
ALTER TABLE bookings DROP CONSTRAINT IF EXISTS bookings_locale_check;
UPDATE bookings SET locale = 'it' WHERE locale NOT IN ('it', 'en');
ALTER TABLE bookings ALTER COLUMN locale SET DEFAULT 'it';
ALTER TABLE bookings ADD CONSTRAINT bookings_locale_check CHECK (locale IN ('it', 'en'));

-- ════════════════════════════════════════════════════════════════════════════
-- 013_inbound_tour_model.sql
-- ════════════════════════════════════════════════════════════════════════════

-- Phase 3: tour model for inbound travel + group departures.
--
-- tours
--   tour_type          private | group | both
--   regions            text[]   Mongolian regions the tour visits (keys from MONGOLIA_REGIONS);
--                               replaces the single `country` column
--   season_months      int[]    months (1-12) the tour can run
--   activities         text[]   horse_riding, hiking, ...
--   accommodation      text[]   hotel, ger_camp, tent, nomad_family, monastery, guesthouse
--   vehicle            text     jeep_4x4 | minivan | mixed
--   price_mode         fixed | from_per_day | on_request
--   price_tiers        jsonb    [{ "minPeople": 2, "maxPeople": 3, "price": 2100 }, ...] per person
--   single_supplement  numeric  extra for a single room, in the tour's currency
-- itinerary days (jsonb) may now carry "overnight" and "region".
--
-- departures: dated group trips people can join.
--
-- Also removes two leftovers of the old outbound business (bookings.include_vat, tours.country_flag).

ALTER TABLE tours
  ADD COLUMN IF NOT EXISTS tour_type text NOT NULL DEFAULT 'both'
    CHECK (tour_type IN ('private', 'group', 'both')),
  ADD COLUMN IF NOT EXISTS regions text[] NOT NULL DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS season_months int[] NOT NULL DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS activities text[] NOT NULL DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS accommodation text[] NOT NULL DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS vehicle text,
  ADD COLUMN IF NOT EXISTS price_mode text NOT NULL DEFAULT 'fixed'
    CHECK (price_mode IN ('fixed', 'from_per_day', 'on_request')),
  ADD COLUMN IF NOT EXISTS price_tiers jsonb NOT NULL DEFAULT '[]'::jsonb,
  ADD COLUMN IF NOT EXISTS single_supplement numeric;

-- Keep the region people already chose.
UPDATE tours
SET regions = ARRAY[country]
WHERE regions = '{}' AND country IS NOT NULL AND country <> '';

ALTER TABLE tours
  DROP COLUMN IF EXISTS country,
  DROP COLUMN IF EXISTS country_flag;

CREATE INDEX IF NOT EXISTS tours_regions_idx ON tours USING gin (regions);
CREATE INDEX IF NOT EXISTS tours_activities_idx ON tours USING gin (activities);

ALTER TABLE bookings DROP COLUMN IF EXISTS include_vat;

-- ─── Departures ──────────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS departures (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tour_id uuid NOT NULL REFERENCES tours(id) ON DELETE CASCADE,
  start_date date NOT NULL,
  end_date date NOT NULL,
  -- NULL = use the tour's price
  price numeric,
  min_participants int NOT NULL DEFAULT 2 CHECK (min_participants >= 1),
  max_participants int NOT NULL DEFAULT 12 CHECK (max_participants >= 1),
  enrolled int NOT NULL DEFAULT 0 CHECK (enrolled >= 0),
  status text NOT NULL DEFAULT 'open'
    CHECK (status IN ('open', 'confirmed', 'full', 'cancelled')),
  notes text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK (end_date >= start_date),
  CHECK (max_participants >= min_participants)
);

CREATE INDEX IF NOT EXISTS departures_tour_idx ON departures(tour_id);
CREATE INDEX IF NOT EXISTS departures_start_idx ON departures(start_date);

DROP TRIGGER IF EXISTS departures_updated_at ON departures;
CREATE TRIGGER departures_updated_at
  BEFORE UPDATE ON departures
  FOR EACH ROW EXECUTE FUNCTION update_updated_at();

ALTER TABLE departures ENABLE ROW LEVEL SECURITY;
-- Visitors see departures of active tours, except cancelled ones.
-- Writes go through the service role (admin API), which bypasses RLS.
DROP POLICY IF EXISTS "departures_public_read" ON departures;
CREATE POLICY "departures_public_read" ON departures FOR SELECT USING (
  status <> 'cancelled'
  AND EXISTS (SELECT 1 FROM tours t WHERE t.id = departures.tour_id AND t.status = 'active')
);

-- ════════════════════════════════════════════════════════════════════════════
-- 014_inquiries.sql
-- ════════════════════════════════════════════════════════════════════════════

-- Phase 4: quote requests and group-departure sign-ups replace the contact form
-- and the online booking funnel.
--
-- inquiries.kind     quote  = quote request (optionally about one tour)
--                    signup = reserve a spot on a group departure (no payment)
-- inquiries.status   new -> quoted -> confirmed | lost
-- A confirmed sign-up counts towards departures.enrolled (the admin API
-- recalculates the total from confirmed sign-ups, so it never drifts).
-- Visitors never read this table: only the server (service role) inserts and reads.

CREATE TABLE IF NOT EXISTS inquiries (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  kind text NOT NULL DEFAULT 'quote' CHECK (kind IN ('quote', 'signup')),
  status text NOT NULL DEFAULT 'new' CHECK (status IN ('new', 'quoted', 'confirmed', 'lost')),
  name text NOT NULL,
  email text NOT NULL,
  phone text,
  country text,
  locale text NOT NULL DEFAULT 'it' CHECK (locale IN ('it', 'en')),
  tour_id uuid REFERENCES tours(id) ON DELETE SET NULL,
  departure_id uuid REFERENCES departures(id) ON DELETE SET NULL,
  travel_from date,
  travel_to date,
  flexible boolean NOT NULL DEFAULT false,
  adults int NOT NULL DEFAULT 1 CHECK (adults BETWEEN 1 AND 50),
  children int NOT NULL DEFAULT 0 CHECK (children BETWEEN 0 AND 50),
  budget_per_day numeric,
  interests text[] NOT NULL DEFAULT '{}',
  accommodation_style text,
  message text,
  admin_notes text,
  is_read boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_inquiries_created_at ON inquiries (created_at DESC);
CREATE INDEX IF NOT EXISTS idx_inquiries_status ON inquiries (status);
CREATE INDEX IF NOT EXISTS idx_inquiries_departure ON inquiries (departure_id) WHERE departure_id IS NOT NULL;

DROP TRIGGER IF EXISTS inquiries_updated_at ON inquiries;
CREATE TRIGGER inquiries_updated_at BEFORE UPDATE ON inquiries
  FOR EACH ROW EXECUTE FUNCTION update_updated_at();

ALTER TABLE inquiries ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Service role full access on inquiries"
  ON inquiries
  FOR ALL
  TO service_role
  USING (true)
  WITH CHECK (true);

-- Keep the messages already received through the old contact form.
INSERT INTO inquiries (kind, name, email, phone, message, is_read, created_at)
SELECT 'quote', name, email, phone,
       CASE WHEN tour_interest IS NULL OR tour_interest = '' THEN message
            ELSE tour_interest || E'\n\n' || message END,
       COALESCE(is_read, false), created_at
FROM contact_submissions;

DROP TABLE IF EXISTS contact_submissions;

-- ════════════════════════════════════════════════════════════════════════════
-- 015_remove_bookings.sql
-- ════════════════════════════════════════════════════════════════════════════

-- Phase 5 decision: no online payment and no bookings. Everything goes through
-- quote requests and group sign-ups (inquiries, migration 014).
--
-- Passport files uploaded by the old booking flow lived in the storage bucket
-- created in 003/005; delete the objects from the Supabase dashboard (Storage),
-- not here, so nothing is removed silently.

DROP TABLE IF EXISTS bookings CASCADE;

